#ifndef MODULES_INTERFACE_HPP
#define MODULES_INTERFACE_HPP

// Calls <name>_mod_init()/<name>_mod_finalize() for every Mods/*_mod module used by
// MCFM, in the same order as the original Modules_Interface.f90. Exposed to Fortran/C
// callers as modules_fi_init_()/modules_fi_finalize_() (see Modules_Interface.cpp).
void modules_fi_init();
void modules_fi_finalize();

#endif
module ppwp2j_mod
  use, intrinsic :: iso_c_binding
  implicit none

  private
    interface
      function get_pp() bind(C, name="ppwp2j_mod_pp")
        import :: c_ptr
        type(c_ptr) :: get_pp
      end function get_pp
    end interface

  public :: pp, ppmax, ppwp2j_mod_init, ppwp2j_mod_finalize

  integer, parameter :: ppmax = 80

  integer(c_int), pointer, dimension(:,:,:,:) :: pp => null()

contains
  subroutine ppwp2j_mod_init()
    implicit none
    integer(c_int), pointer, dimension(:,:,:,:) :: temp_ptr => null()

    call c_f_pointer(get_pp(), temp_ptr, [9,9,9,9])
    pp(-4:,-4:,-4:,-4:) => temp_ptr
    temp_ptr => null()
  end subroutine ppwp2j_mod_init

  subroutine ppwp2j_mod_finalize()
    implicit none
    nullify(pp)
  end subroutine ppwp2j_mod_finalize
end module ppwp2j_mod
