#ifndef TYPES_H
#define TYPES_H

// Translation of the Fortran module `types` (types_mod.f). That module only
// defines KIND parameters (sp, dp, ex, qp) used to select real/complex
// precision in declarations such as real(dp) and complex(dp); it has no
// executable statements and no module variables. Per this project's rewrite
// rules, real(dp) and complex(dp) are translated directly to `double` and
// `std::complex<double>` at each call site, so no translated C++ code needs
// to reference a symbol from this module — the namespace is kept only so a
// `using namespace types;` following a former `use types` is harmless.

namespace types {
}

#endif

