#include <Modules_Interface.hpp>

// Each already-translated Mods/<name>_mod module still keeps its <name>_mod_init()
// and <name>_mod_finalize() subroutines in Fortran (they establish/tear down the
// c_f_pointer contract with the C++-owned data for that module). This file only
// orchestrates calling all of them in the original source order, so those Fortran
// module procedures are declared here via their gfortran mangled names rather than
// invented C++ equivalents.
extern "C" {
  void __ewcharge_mod_MOD_ewcharge_mod_init();
  void __zcouple_mod_MOD_zcouple_mod_init();
  void __b0_mod_MOD_b0_mod_init();
  void __blha_mod_MOD_blha_mod_init();
  void __cabibbo_mod_MOD_cabibbo_mod_init();
  void __ggzzintegrals_mod_MOD_ggzzintegrals_mod_init();
  void __part_mod_MOD_part_mod_finalize();
  void __zprods_com_mod_MOD_zprods_com_mod_finalize();
  void __zprods_decl_mod_MOD_zprods_decl_mod_finalize();
  void __mmsq_cs_mod_MOD_mmsq_cs_mod_finalize();
  void __mqq_mod_MOD_mqq_mod_finalize();
  void __msq_cs_mod_MOD_msq_cs_mod_finalize();
  void __msq_struc_mod_MOD_msq_struc_mod_finalize();

  // Added by the integration step, not present in the original
  // Modules_Interface.f90: pp_mod and ppwp2j_mod used to hold their `pp` tables
  // as save'd, data-initialized Fortran arrays needing no runtime setup. Their
  // C++ translation moved the tables into C++ storage, so their Fortran views
  // are now c_f_pointer pointers that must be established here like every other
  // translated module's; without this they stay null in the still-Fortran
  // callers Z2jet/qqb_z2jetx_new.f and W2jet/qqb_wp2jetx_new.f.
  void __pp_mod_MOD_pp_mod_init();
  void __ppwp2j_mod_MOD_ppwp2j_mod_init();
  void __pp_mod_MOD_pp_mod_finalize();
  void __ppwp2j_mod_MOD_ppwp2j_mod_finalize();
}

